<script>
(function(){
  function g(id){return document.getElementById(id);}
  function esc(v){
    if(v==null)return '';
    return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  var rawEl=g('lolrelraw'); if(!rawEl)return;
  var raw=(rawEl.value||'').replace(/<\/?LOL_RELATION>/gi,'').trim();
  var d={}; try{d=JSON.parse(raw);}catch(e){}
  var TH=(d.lang==='th');
  var relations=Array.isArray(d.relations)?d.relations:[];

  var RC={
