  function build(){
    var sg=g('lolrelsigil');
    if(sg)sg.innerHTML=sigilPath(d.region);
    var nm=g('lolrelnm');
    if(nm)nm.textContent=d.character||'—';
    var ct=g('lolrelcount');
    if(ct)ct.textContent=relations.length+(TH?' แชมเปี้ยน':(' Champion'+(relations.length!==1?'s':'')));
    var ft=g('lolrelfoot');
    if(ft)ft.textContent=TH?'ระบบสายสัมพันธ์ — รูนเทอร์รา':'RUNETERRA BONDS';
    var list=g('lolrellist');
    if(!list)return;
    if(!relations.length){
      list.innerHTML='<div class="lolrel-empty">'+(TH?'ยังไม่มีความสัมพันธ์บันทึกไว้':'No relationships recorded yet')+'</div>';
      return;
    }
    list.innerHTML=relations.map(buildCard).join('');
  }

  build();

  function sendToChat(txt){
    setTimeout(function(){
      try{
        var w=window.parent||window;
        var ta=w.document.getElementById('send_textarea')||w.document.querySelector('#textareaAutosize,textarea.chat-input,textarea');
        if(ta){
          var dd=Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype,'value');
          if(dd&&dd.set)dd.set.call(ta,txt);else ta.value=txt;
          ta.dispatchEvent(new Event('input',{bubbles:true}));
          setTimeout(function(){
            try{
              var sb=w.document.getElementById('send_but');
              if(sb)sb.click();
              else ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));
            }catch(e){}
          },150);
          return;
        }
      }catch(e){}
      try{navigator.clipboard.writeText(txt);}catch(e){}
    },450);
  }

  var hd=g('lolrelhead');
  if(hd)hd.addEventListener('click',function(){g('lolrelwin').classList.toggle('closed');});

  var list=g('lolrellist');
  if(list){
    list.addEventListener('click',function(e){
      var card=e.target.closest('.lolrel-card'); if(!card)return;
      var rid=card.getAttribute('data-rid');

      if(e.target.classList.contains('lolrel-btn-edit')){
        var ed=card.querySelector('.lolrel-edit');
        if(ed)ed.classList.toggle('on');
        return;
      }
      if(e.target.classList.contains('lolrel-btn-cancel')){
        var ed2=card.querySelector('.lolrel-edit');
        if(ed2)ed2.classList.remove('on');
        return;
      }
      if(e.target.classList.contains('lolrel-btn-save')){
        var sc=parseInt(card.querySelector('.lolrel-inp-score').value)||0;
        var lv=parseInt(card.querySelector('.lolrel-inp-lvl').value)||0;
        var st=card.querySelector('.lolrel-inp-status').value||'';
        var nt=card.querySelector('.lolrel-inp-note').value||'';
        var relName='';
        for(var i=0;i<relations.length;i++){if(String(relations[i].id)===String(rid)){relName=relations[i].name||'';break;}}
        sendToChat('<'+'LOL_RELATION_EDIT>'+JSON.stringify({id:parseInt(rid),name:relName,score:sc,level:lv,status:st,note:nt})+'<'+'/LOL_RELATION_EDIT>');
        var ed3=card.querySelector('.lolrel-edit');
        if(ed3)ed3.classList.remove('on');
        return;
      }
      if(e.target.classList.contains('lolrel-btn-del')){
        var relName2='';
        for(var j=0;j<relations.length;j++){if(String(relations[j].id)===String(rid)){relName2=relations[j].name||'';break;}}
        var msg=TH?('ลบความสัมพันธ์กับ '+relName2+'?'):('Remove relationship with '+relName2+'?');
        if(confirm(msg)){
          sendToChat('<'+'LOL_RELATION_DELETE>'+JSON.stringify({id:parseInt(rid),name:relName2})+'<'+'/LOL_RELATION_DELETE>');
        }
        return;
      }
    });

    list.addEventListener('input',function(e){
      var card=e.target.closest('.lolrel-card'); if(!card)return;
      if(e.target.classList.contains('lolrel-inp-score')){
        var d2=card.querySelector('.lolrel-scval');
        if(d2)d2.textContent=e.target.value;
      }
      if(e.target.classList.contains('lolrel-inp-lvl')){
        var d3=card.querySelector('.lolrel-lvval');
        if(d3)d3.textContent=e.target.value;
      }
    });
  }
})();
</script>
